/// <summary>
/// UI builder class for sales order automate
/// </summary>
class METSalesOrderFinalizationAutomateUIBuilder extends SrsReportDataContractUIBuilder
{
    METSalesOrderFinalizationAutomateContract   contract;
    DialogField		                            warehouseListDlg;


}

Method.Source:
/// <summary>
/// Post build method
/// </summary>
public void postBuild()
{
    contract		= this.dataContractObject() as METSalesOrderFinalizationAutomateContract;
    warehouseListDlg    = this.bindInfo().getDialogField(contract, methodStr(METSalesOrderFinalizationAutomateContract, parmWarehouseList));

    warehouseListDlg.lookupButton(FormLookupButton::Always);
}

/// <summary>
/// Post run method
/// </summary>
public void postRun()
{
    Query		            query		    = new Query();
    QueryBuildDataSource    qbdsWarehouse = query.addDataSource(tablenum(InventLocation));

    qbdsWarehouse.addRange(fieldNum(InventLocation, METAutomateSalesFinalization)).value(queryValue(NoYes::Yes));

    qbdsWarehouse.fields().addField(fieldNum(InventLocation, InventLocationId));
    qbdsWarehouse.fields().addField(fieldNum(InventLocation, Name));

    container selectedFields = [tableNum(InventLocation), fieldNum(InventLocation, InventLocationId)];

    SysLookupMultiSelectCtrl::constructWithQuery(this.dialog().dialogForm().formRun(), warehouseListDlg.control(), query, false, selectedFields);
}
